/* eslint-disable @typescript-eslint/no-explicit-any */
import {describe, expect, test, beforeEach, afterEach, jest} from "@jest/globals";

// Mock Firebase Admin and Functions
const mockSet = jest.fn<() => Promise<void>>();
const mockGet = jest.fn<() => Promise<{exists: boolean; data?: () => any}>>();
const mockDoc = jest.fn(() => ({
  get: mockGet,
  set: mockSet,
}));
const mockCollection = jest.fn(() => ({
  doc: mockDoc,
}));

const mockFirestore = jest.fn(() => ({
  collection: mockCollection,
  FieldValue: {
    serverTimestamp: jest.fn(() => "MOCK_SERVER_TIMESTAMP"),
  },
}));

const mockConsoleLog = jest.fn();
const mockConsoleError = jest.fn();

// Mock console methods
jest.spyOn(console, "log").mockImplementation(mockConsoleLog);
jest.spyOn(console, "error").mockImplementation(mockConsoleError);

jest.mock("firebase-admin", () => ({
  firestore: mockFirestore,
}));

// Mock the openaiService
const mockGenerateUniqueRiddle = jest.fn<() => Promise<[string, string] | null>>();
jest.mock("../openaiService", () => ({
  generateUniqueRiddle: mockGenerateUniqueRiddle,
}));

// Mock firebase-functions/v2/scheduler
const mockScheduledFunction = jest.fn<(context: any) => Promise<void>>();
jest.mock("firebase-functions/v2/scheduler", () => ({
  onSchedule: jest.fn((config, handler) => {
    mockScheduledFunction.mockImplementation(handler as any);
    return mockScheduledFunction;
  }),
}));

describe("Daily Challenge Scheduler", () => {
  beforeEach(() => {
    // Clear all mocks
    jest.clearAllMocks();

    // Reset environment variables
    delete process.env.OPENAI_API_KEY;

    // Re-import the module to trigger the mock setup
    require("../dailyScheduler");
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe("Scheduler configuration", () => {
    test("should be configured with correct schedule and timezone", () => {
      // Verify that onSchedule was called with correct configuration
      const onScheduleMock = require("firebase-functions/v2/scheduler").onSchedule;
      expect(onScheduleMock).toHaveBeenCalledWith(
        {
          schedule: "0 0 * * *", // Daily at 00:00 UTC
          timeZone: "UTC",
          secrets: ["OPENAI_API_KEY"],
        },
        expect.any(Function),
      );
    });
  });

  describe("Daily challenge generation", () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = "test-openai-key";
    });

    test("should generate new daily challenge when none exists", async () => {
      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["What has four legs but cannot walk?", "table"]);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify the flow
      expect(mockConsoleLog).toHaveBeenCalledWith("Daily challenge scheduler started.");
      expect(mockGet).toHaveBeenCalled();
      expect(mockGenerateUniqueRiddle).toHaveBeenCalled();
      expect(mockSet).toHaveBeenCalled();
      expect(mockConsoleLog).toHaveBeenCalledWith("Daily challenge scheduler finished successfully.");
    });

    test("should skip generation if challenge already exists for today", async () => {
      const today = new Date().toISOString().split("T")[0];

      // Mock existing challenge for today
      mockGet.mockResolvedValue({
        exists: true,
        data: () => ({date: today}),
      });

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify it skips generation
      expect(mockConsoleLog).toHaveBeenCalledWith("Daily challenge scheduler started.");
      expect(mockConsoleLog).toHaveBeenCalledWith(`Daily challenge already exists for ${today}. Skipping generation.`);
      expect(mockGenerateUniqueRiddle).not.toHaveBeenCalled();
      expect(mockSet).not.toHaveBeenCalled();
    });

    test("should replace existing challenge if it's for a different date", async () => {
      const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split("T")[0];

      // Mock existing challenge for yesterday
      mockGet.mockResolvedValue({
        exists: true,
        data: () => ({date: yesterday}),
      });

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["What runs but never walks?", "river"]);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify it generates new challenge
      expect(mockGenerateUniqueRiddle).toHaveBeenCalled();
      expect(mockSet).toHaveBeenCalled();
      expect(mockConsoleLog).toHaveBeenCalledWith("Daily challenge scheduler finished successfully.");
    });

    test("should handle missing OPENAI_API_KEY", async () => {
      delete process.env.OPENAI_API_KEY;

      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify it exits early
      expect(mockConsoleError).toHaveBeenCalledWith(
        "OPENAI_API_KEY environment variable is required for daily challenge generation",
      );
      expect(mockGenerateUniqueRiddle).not.toHaveBeenCalled();
      expect(mockSet).not.toHaveBeenCalled();
    });

    test("should handle riddle generation failure", async () => {
      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock failed riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(null);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify it handles failure gracefully
      expect(mockConsoleError).toHaveBeenCalledWith("Failed to generate riddle using OpenAI for daily challenge");
      expect(mockSet).not.toHaveBeenCalled();
    });

    test("should create challenge with correct structure", async () => {
      const today = new Date().toISOString().split("T")[0];

      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      const testRiddle: [string, string] = ["What gets wet while drying?", "towel"];
      mockGenerateUniqueRiddle.mockResolvedValue(testRiddle);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify the challenge structure
      expect(mockSet).toHaveBeenCalledWith({
        riddleId: `daily_${today}`,
        text: testRiddle[0],
        answer: testRiddle[1],
        date: today,
        createdAt: "MOCK_SERVER_TIMESTAMP",
        generatedBy: "openai",
      });
    });

    test("should log riddle generation details", async () => {
      const today = new Date().toISOString().split("T")[0];

      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      const testRiddle: [string, string] = ["What has keys but no locks?", "piano"];
      mockGenerateUniqueRiddle.mockResolvedValue(testRiddle);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify logging
      expect(mockConsoleLog).toHaveBeenCalledWith(`Generating daily challenge for date: ${today}`);
      expect(mockConsoleLog).toHaveBeenCalledWith(`Generating fresh riddle using OpenAI for ${today}...`);
      expect(mockConsoleLog).toHaveBeenCalledWith(
        `Successfully generated daily riddle: "${testRiddle[0]}" → "${testRiddle[1]}"`,
      );
      expect(mockConsoleLog).toHaveBeenCalledWith(`Daily challenge set for ${today}: "${testRiddle[0]}"`);
    });
  });

  describe("Error handling", () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = "test-openai-key";
    });

    test("should handle Firestore get errors", async () => {
      // Mock Firestore get error
      mockGet.mockRejectedValue(new Error("Firestore connection failed"));

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify error handling
      expect(mockConsoleError).toHaveBeenCalledWith("Error running daily challenge scheduler:", expect.any(Error));
      expect(mockGenerateUniqueRiddle).not.toHaveBeenCalled();
      expect(mockSet).not.toHaveBeenCalled();
    });

    test("should handle riddle generation errors", async () => {
      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock riddle generation error
      mockGenerateUniqueRiddle.mockRejectedValue(new Error("OpenAI API error"));

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify error handling
      expect(mockConsoleError).toHaveBeenCalledWith("Error running daily challenge scheduler:", expect.any(Error));
      expect(mockSet).not.toHaveBeenCalled();
    });

    test("should handle Firestore set errors", async () => {
      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["What's black and white and red all over?", "newspaper"]);

      // Mock Firestore set error
      mockSet.mockRejectedValue(new Error("Firestore write failed"));

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify error handling
      expect(mockConsoleError).toHaveBeenCalledWith("Error running daily challenge scheduler:", expect.any(Error));
    });

    test("should handle malformed existing challenge data", async () => {
      // Mock existing challenge with malformed data
      mockGet.mockResolvedValue({
        exists: true,
        data: () => ({}), // Missing date field
      });

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["What goes up but never comes down?", "age"]);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify it generates new challenge when data is malformed
      expect(mockGenerateUniqueRiddle).toHaveBeenCalled();
      expect(mockSet).toHaveBeenCalled();
    });
  });

  describe("Date handling", () => {
    test("should use consistent date format", async () => {
      // Mock the Date constructor to return a specific date
      const mockDate = new Date("2024-01-15T10:30:00Z");
      jest.spyOn(global, "Date").mockImplementation(() => mockDate);

      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["Test riddle", "test"]);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Verify date format (YYYY-MM-DD)
      expect(mockConsoleLog).toHaveBeenCalledWith("Generating daily challenge for date: 2024-01-15");
      expect(mockSet).toHaveBeenCalledWith(
        expect.objectContaining({
          riddleId: "daily_2024-01-15",
          date: "2024-01-15",
        }),
      );

      // Restore Date
      jest.restoreAllMocks();
    });

    test("should handle timezone correctly (UTC)", async () => {
      // Create a date that would be different in different timezones
      const mockDate = new Date("2024-01-15T23:30:00-05:00"); // 11:30 PM EST = 4:30 AM UTC next day
      jest.spyOn(global, "Date").mockImplementation(() => mockDate);

      // Mock no existing challenge
      mockGet.mockResolvedValue({exists: false});

      // Mock successful riddle generation
      mockGenerateUniqueRiddle.mockResolvedValue(["Test riddle", "test"]);

      // Mock successful Firestore set
      mockSet.mockResolvedValue(undefined);

      // Execute the scheduler function
      await mockScheduledFunction({});

      // Should use UTC date (next day) not local date
      expect(mockConsoleLog).toHaveBeenCalledWith("Generating daily challenge for date: 2024-01-16");

      // Restore Date
      jest.restoreAllMocks();
    });
  });
});
